Status ValidateStructureReply::validate() const {
    if (issue_codes.size() > 256u) {
        return Status::InvalidArgument;
    }
    for (const auto& v : issue_codes) {
        if (v > 65535u) {
            return Status::InvalidArgument;
        }
    }
    if (issue_messages.size() > 256u) {
        return Status::InvalidArgument;
    }
    for (const auto& v : issue_messages) {
        if (v.size() > 192u || !is_valid_text(v)) {
            return Status::InvalidArgument;
        }
    }
    if (issue_messages.size() != issue_codes.size()) {
        return Status::InvalidArgument;
    }
    return Status::Ok;
}

Status ValidateStructureReply::encode(Writer& writer) const {
    if (const Status valid = validate(); valid != Status::Ok) {
        return valid;
    }
    writer.write_array_header(4);
    writer.write_bool(ok);
    writer.write_bool(truncated);
    writer.write_array_header(issue_codes.size());
    for (const auto& v : issue_codes) {
        writer.write_uint(v);
    }
    writer.write_array_header(issue_messages.size());
    for (const auto& v : issue_messages) {
        writer.write_string(v);
    }
    return writer.status();
}

Result<ValidateStructureReply> ValidateStructureReply::decode(Reader& reader) {
    ValidateStructureReply m;
    Status s = reader.expect_array(4);
    if (s == Status::Ok) {
        s = reader.read_bool(m.ok);
    }
    if (s == Status::Ok) {
        s = reader.read_bool(m.truncated);
    }
    if (s == Status::Ok) {
        std::size_t count = 0;
        s = reader.read_array_header(count, 256);
        if (s == Status::Ok) {
            m.issue_codes.reserve(count);
            for (std::size_t i = 0; i < count && s == Status::Ok; ++i) {
                std::uint32_t v{};
                s = reader.read_u32(v, 0u, 65535u);
                if (s == Status::Ok) {
                    m.issue_codes.push_back(std::move(v));
                }
            }
        }
    }
    if (s == Status::Ok) {
        std::size_t count = 0;
        s = reader.read_array_header(count, 256);
        if (s == Status::Ok) {
            m.issue_messages.reserve(count);
            for (std::size_t i = 0; i < count && s == Status::Ok; ++i) {
                std::string v{};
                s = reader.read_string(v, 192);
                if (s == Status::Ok) {
                    m.issue_messages.push_back(std::move(v));
                }
            }
        }
    }
    if (s == Status::Ok) {
        s = m.validate();
        if (s != Status::Ok) {
            reader.fail(s, "message violates a schema limit");
        }
    }
    if (s != Status::Ok) {
        return {s, ValidateStructureReply{}, reader.detail()};
    }
    return {Status::Ok, std::move(m), ""};
}

namespace {

template <class Variant, class T>
Result<Variant> lift(Result<T>&& result) {
    if (!result.ok()) {
        return {result.status, Variant{}, result.detail};
    }
    return {Status::Ok, Variant{std::in_place_type<T>, std::move(result.value)}, ""};
}

}  // namespace

Result<RequestPayload> decode_request_payload(MessageType type, Reader& reader) {
    switch (type) {
        case MessageType::Hello:
            return lift<RequestPayload>(Hello::decode(reader));
        case MessageType::Ping:
            return lift<RequestPayload>(Ping::decode(reader));
        case MessageType::Shutdown:
            return lift<RequestPayload>(Shutdown::decode(reader));
        case MessageType::AttachSlotRing:
            return lift<RequestPayload>(AttachSlotRing::decode(reader));
        case MessageType::OpenDocument:
            return lift<RequestPayload>(OpenDocument::decode(reader));
        case MessageType::CloseDocument:
            return lift<RequestPayload>(CloseDocument::decode(reader));
        case MessageType::GetDocumentInfo:
            return lift<RequestPayload>(GetDocumentInfo::decode(reader));
        case MessageType::GetPageSizes:
            return lift<RequestPayload>(GetPageSizes::decode(reader));
        case MessageType::GetOutline:
            return lift<RequestPayload>(GetOutline::decode(reader));
        case MessageType::GetPageLinks:
            return lift<RequestPayload>(GetPageLinks::decode(reader));
        case MessageType::GetLinkUri:
            return lift<RequestPayload>(GetLinkUri::decode(reader));
        case MessageType::GetPageBoxes:
            return lift<RequestPayload>(GetPageBoxes::decode(reader));
        case MessageType::GetPageText:
            return lift<RequestPayload>(GetPageText::decode(reader));
        case MessageType::SearchPage:
            return lift<RequestPayload>(SearchPage::decode(reader));
        case MessageType::RenderTile:
            return lift<RequestPayload>(RenderTile::decode(reader));
        case MessageType::CancelBefore:
            return lift<RequestPayload>(CancelBefore::decode(reader));
        case MessageType::ValidateStructure:
            return lift<RequestPayload>(ValidateStructure::decode(reader));
    }
    return {Status::ProtocolError, RequestPayload{}, "unknown message type"};
}

Result<ReplyPayload> decode_reply_payload(MessageType type, Reader& reader) {
    switch (type) {
        case MessageType::Hello:
            return lift<ReplyPayload>(HelloReply::decode(reader));
        case MessageType::Ping:
            return lift<ReplyPayload>(Pong::decode(reader));
        case MessageType::Shutdown:
            return lift<ReplyPayload>(ShutdownReply::decode(reader));
        case MessageType::AttachSlotRing:
            return lift<ReplyPayload>(AttachSlotRingReply::decode(reader));
        case MessageType::OpenDocument:
            return lift<ReplyPayload>(OpenDocumentReply::decode(reader));
        case MessageType::CloseDocument:
            return lift<ReplyPayload>(CloseDocumentReply::decode(reader));
        case MessageType::GetDocumentInfo:
            return lift<ReplyPayload>(GetDocumentInfoReply::decode(reader));
        case MessageType::GetPageSizes:
            return lift<ReplyPayload>(GetPageSizesReply::decode(reader));
        case MessageType::GetOutline:
            return lift<ReplyPayload>(GetOutlineReply::decode(reader));
        case MessageType::GetPageLinks:
            return lift<ReplyPayload>(GetPageLinksReply::decode(reader));
        case MessageType::GetLinkUri:
            return lift<ReplyPayload>(GetLinkUriReply::decode(reader));
        case MessageType::GetPageBoxes:
            return lift<ReplyPayload>(GetPageBoxesReply::decode(reader));
        case MessageType::GetPageText:
            return lift<ReplyPayload>(GetPageTextReply::decode(reader));
        case MessageType::SearchPage:
            return lift<ReplyPayload>(SearchPageReply::decode(reader));
        case MessageType::RenderTile:
            return lift<ReplyPayload>(RenderTileReply::decode(reader));
        case MessageType::CancelBefore:
            return lift<ReplyPayload>(CancelBeforeReply::decode(reader));
        case MessageType::ValidateStructure:
            return lift<ReplyPayload>(ValidateStructureReply::decode(reader));
    }
    return {Status::ProtocolError, ReplyPayload{}, "unknown message type"};
}

